<body>
  <a class="skip-link" href="#main-content">Skip to content</a>
  <div class="viz-menu" aria-label="Visualization menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Open menu">☰</button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="downloadImage()">Download PNG</button>
      <button onclick="window.print()">Print</button>
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span> <span id="themeLabel">Dark</span></button>
    </div>
  </div>
  <main id="main-content" class="poster">
    <section class="hero-header animate">
      <header>
        <div class="eyebrow">Artificial Analysis Intelligence Index v4.0</div>
        <h1>Frontier AI Models Compared</h1>
        <p class="subtitle">A data-forward guide to choosing among 10 leading language models by intelligence, output speed, and blended token price.</p>
      </header>
      <aside class="takeaway">
        <h2>No single “best” model.</h2>
        <p>The right choice depends on what matters most: top reasoning, low latency, or token economics. The price gap alone spans a staggering <strong>33×</strong>.</p>
      </aside>
    </section>

    <section class="metric-grid animate delay-1" aria-label="Topline metrics">
      <article class="stat-card blue"><div class="stat-label">Highest Intelligence</div><div class="stat-value">57 <span class="stat-unit">AA Index</span></div><div class="stat-context">Gemini 3.1 Pro Preview and GPT-5.4 tie for the lead.</div></article>
      <article class="stat-card teal"><div class="stat-label">Fastest Speed</div><div class="stat-value">206 <span class="stat-unit">tok/s</span></div><div class="stat-context">gpt-oss-120B is the throughput champion.</div></article>
      <article class="stat-card amber"><div class="stat-label">Lowest Price</div><div class="stat-value">$0.30 <span class="stat-unit">/1M tokens</span></div><div class="stat-context">gpt-oss-120B and DeepSeek V3.2 are tied.</div></article>
      <article class="stat-card rose"><div class="stat-label">Price Range</div><div class="stat-value">33× <span class="stat-unit">spread</span></div><div class="stat-context">From $0.30 to Claude Opus 4.6 at $10.00.</div></article>
    </section>

    <section class="hero-chart-section animate delay-2" aria-labelledby="tradeoff-title">
      <div class="section-title-row">
        <div><div class="section-kicker">Visual Centerpiece</div><h2 id="tradeoff-title">The Intelligence–Speed–Cost Trade-Off</h2></div>
        <p class="section-note">Each bubble plots speed against intelligence. Bubble size encodes price per 1M tokens; labels reveal the model-selection tension.</p>
      </div>
      <div class="chart-wrap"><canvas id="tradeoffChart" role="img" aria-label="Bubble chart comparing model intelligence, output speed, and price"></canvas></div>
      <div class="legend-strip">
        <span class="legend-item"><i class="dot teal"></i>Best value / low cost</span>
        <span class="legend-item"><i class="dot"></i>Frontier intelligence</span>
        <span class="legend-item"><i class="dot amber"></i>Balanced middle ground</span>
        <span class="legend-item"><i class="dot rose"></i>Premium cost tier</span>
        <span>Bubble area scales with blended USD per 1M tokens.</span>
      </div>
      <div class="insight-grid">
        <article class="insight-card"><h3>Intelligence leaders</h3><p>Gemini 3.1 Pro and GPT-5.4 sit at the top with 57, but neither wins on speed or price.</p></article>
        <article class="insight-card"><h3>Fast ≠ smart</h3><p>gpt-oss-120B produces 206 tok/s at $0.30, yet has the lowest intelligence score in the plotted set.</p></article>
        <article class="insight-card"><h3>Balanced pick</h3><p>Gemini 3 Flash pairs 46 intelligence with 149 tok/s at only $1.10 per 1M tokens.</p></article>
      </div>
    </section>

    <section class="three-charts animate delay-3" aria-label="Dimension-by-dimension comparisons">
      <article class="mini-panel"><h2>Intelligence Rankings</h2><p>Top scores cluster tightly, but the complete three-metric set spans from 33 to 57 on the AA Index.</p><div class="mini-chart-wrap"><canvas id="intelligenceChart" role="img" aria-label="Horizontal bar chart of intelligence scores"></canvas></div></article>
      <article class="mini-panel"><h2>Output Speed</h2><p>Latency-sensitive apps should look beyond index rank: budget and open-weight models dominate throughput.</p><div class="mini-chart-wrap"><canvas id="speedChart" role="img" aria-label="Horizontal bar chart of output speed in tokens per second"></canvas></div><div class="speed-hook">Key hook: fastest model ranks last on intelligence.</div></article>
      <article class="mini-panel"><h2>Pricing Landscape</h2><p>Token economics vary wildly: the cheapest models are $0.30 while Claude Opus reaches $10.00 per 1M tokens.</p><div class="mini-chart-wrap"><canvas id="priceChart" role="img" aria-label="Horizontal bar chart of model prices per one million tokens"></canvas></div></article>
    </section>

    <section class="method-section animate delay-4" aria-label="Methodology and ranked source data">
      <article class="method-box">
        <h2>About the Index</h2>
        <p>The Artificial Analysis Intelligence Index v4.0 aggregates 10 independent evaluations spanning coding, agentic tasks, scientific reasoning, knowledge accuracy, hallucination resistance, and instruction following under standardized conditions.</p>
        <div class="benchmarks"><span class="chip">GDPval-AA</span><span class="chip">τ²-Bench Telecom</span><span class="chip">Terminal-Bench Hard</span><span class="chip">SciCode</span><span class="chip">AA-LCR</span><span class="chip">AA-Omniscience</span><span class="chip">IFBench</span><span class="chip">Humanity’s Last Exam</span><span class="chip">GPQA Diamond</span><span class="chip">CritPt</span></div>
      </article>
      <article class="rank-box">
        <h2>Complete 3-Metric Set</h2>
        <div class="rank-list" id="rankList"></div>
      </article>
    </section>
    <footer><span>Source: Artificial Analysis Intelligence Index v4.0; pricing is blended input/output USD per 1M tokens.</span><span>A1 portrait comparison poster · 10 models with intelligence, speed, and price data</span></footer>
  </main>

  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      var menu = document.querySelector('.viz-menu');
      if (menu && !menu.contains(e.target)) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    var modelData = [
      {model:'Gemini 3.1 Pro', full:'Gemini 3.1 Pro Preview', intelligence:57, speed:129, price:4.50, color:'#38BDF8'},
      {model:'GPT-5.4', full:'GPT-5.4 (xhigh)', intelligence:57, speed:72, price:5.60, color:'#38BDF8'},
      {model:'Claude Opus 4.6', full:'Claude Opus 4.6 (max)', intelligence:53, speed:40, price:10.00, color:'#FB7185'},
      {model:'Claude Sonnet 4.6', full:'Claude Sonnet 4.6 (max)', intelligence:52, speed:48, price:6.00, color:'#A78BFA'},
      {model:'GLM-5.1', full:'GLM-5.1', intelligence:51, speed:40, price:2.10, color:'#F59E0B'},
      {model:'Grok 4.20', full:'Grok 4.20 0309 v2', intelligence:49, speed:162, price:3.00, color:'#F59E0B'},
      {model:'Gemini 3 Flash', full:'Gemini 3 Flash', intelligence:46, speed:149, price:1.10, color:'#FBBF24'},
      {model:'DeepSeek V3.2', full:'DeepSeek V3.2', intelligence:42, speed:31, price:0.30, color:'#2DD4BF'},
      {model:'NVIDIA Nemotron 3', full:'NVIDIA Nemotron 3 Super', intelligence:36, speed:193, price:0.40, color:'#2DD4BF'},
      {model:'gpt-oss-120B', full:'gpt-oss-120B (high)', intelligence:33, speed:206, price:0.30, color:'#2DD4BF'}
    ];
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart; this.charts.set(canvasId, chart); return chart;
        } catch (e) { console.error('Chart initialization failed for ' + canvasId + ':', e); return null; }
      }
    };
    var labelPlugin = {
      id: 'customLabels',
      afterDatasetsDraw: function(chart) {
        var ctx = chart.ctx;
        ctx.save();
        var meta = chart.getDatasetMeta(0);
        meta.data.forEach(function(point, index) {
          var item = modelData[index];
          ctx.font = '700 24px Inter, sans-serif';
          ctx.fillStyle = '#EAF6FF';
          ctx.textAlign = item.speed > 160 ? 'right' : 'left';
          ctx.textBaseline = 'middle';
          var xOffset = item.speed > 160 ? -18 : 18;
          var yOffset = item.model === 'GPT-5.4' ? 20 : (item.model === 'Gemini 3.1 Pro' ? -22 : 0);
          ctx.fillText(item.model, point.x + xOffset, point.y + yOffset);
        });
        ctx.restore();
      }
    };
    function axisColors() {
      var isDark = document.documentElement.classList.contains('theme-dark');
      return { text: isDark ? '#DCE8F8' : '#0F172A', muted: isDark ? '#8EA0B7' : '#64748B', grid: isDark ? 'rgba(255,255,255,0.10)' : 'rgba(15,23,42,0.10)' };
    }
    function baseBarOptions(colors, maxX, formatter) {
      return {
        indexAxis: 'y', responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false }, tooltip: { enabled: true, callbacks: { label: function(ctx) { return formatter(ctx.raw); } } } },
        scales: {
          x: { min: 0, max: maxX, grid: { color: colors.grid }, ticks: { color: colors.muted, font: { size: 18, weight: 650 } } },
          y: { grid: { display: false }, ticks: { color: colors.text, font: { size: 18, weight: 700 } } }
        }
      };
    }
    function buildTradeoffChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var colors = axisColors();
      ChartManager.safeInit('tradeoffChart', {
        type: 'bubble', data: { datasets: [{ label: 'Models', data: modelData.map(function(d) { return { x: d.speed, y: d.intelligence, r: 15 + Math.sqrt(d.price) * 18 }; }), backgroundColor: modelData.map(function(d) { return d.color + 'B8'; }), borderColor: modelData.map(function(d) { return d.color; }), borderWidth: 4, hoverBorderWidth: 5 }] },
        options: {
          responsive: true, maintainAspectRatio: false, layout: { padding: { top: 40, right: 160, bottom: 20, left: 18 } },
          plugins: { legend: { display: false }, tooltip: { enabled: true, callbacks: { label: function(ctx) { var d = modelData[ctx.dataIndex]; return d.full + ': ' + d.intelligence + ' index, ' + d.speed + ' tok/s, $' + d.price.toFixed(2) + '/1M'; } } } },
          scales: {
            x: { min: 20, max: 220, title: { display: true, text: 'Output speed (tokens/sec) →', color: colors.text, font: { size: 28, weight: 800 } }, grid: { color: colors.grid }, ticks: { color: colors.muted, font: { size: 22, weight: 650 } } },
            y: { min: 30, max: 60, title: { display: true, text: 'Artificial Analysis Intelligence Index →', color: colors.text, font: { size: 28, weight: 800 } }, grid: { color: colors.grid }, ticks: { color: colors.muted, font: { size: 22, weight: 650 } } }
          }
        }, plugins: [labelPlugin]
      });
    }
    function buildBarCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var colors = axisColors();
      var intel = modelData.slice().sort(function(a,b) { return b.intelligence - a.intelligence; });
      var speed = modelData.slice().sort(function(a,b) { return b.speed - a.speed; });
      var price = modelData.slice().sort(function(a,b) { return a.price - b.price; });
