        scales: {
          x: { min: 0, max: maxX, grid: { color: colors.grid }, ticks: { color: colors.muted, font: { size: 18, weight: 650 } } },
          y: { grid: { display: false }, ticks: { color: colors.text, font: { size: 18, weight: 700 } } }
        }
      };
    }
    function buildTradeoffChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var colors = axisColors();
      ChartManager.safeInit('tradeoffChart', {
        type: 'bubble', data: { datasets: [{ label: 'Models', data: modelData.map(function(d) { return { x: d.speed, y: d.intelligence, r: 15 + Math.sqrt(d.price) * 18 }; }), backgroundColor: modelData.map(function(d) { return d.color + 'B8'; }), borderColor: modelData.map(function(d) { return d.color; }), borderWidth: 4, hoverBorderWidth: 5 }] },
        options: {
          responsive: true, maintainAspectRatio: false, layout: { padding: { top: 40, right: 160, bottom: 20, left: 18 } },
          plugins: { legend: { display: false }, tooltip: { enabled: true, callbacks: { label: function(ctx) { var d = modelData[ctx.dataIndex]; return d.full + ': ' + d.intelligence + ' index, ' + d.speed + ' tok/s, $' + d.price.toFixed(2) + '/1M'; } } } },
          scales: {
            x: { min: 20, max: 220, title: { display: true, text: 'Output speed (tokens/sec) →', color: colors.text, font: { size: 28, weight: 800 } }, grid: { color: colors.grid }, ticks: { color: colors.muted, font: { size: 22, weight: 650 } } },
            y: { min: 30, max: 60, title: { display: true, text: 'Artificial Analysis Intelligence Index →', color: colors.text, font: { size: 28, weight: 800 } }, grid: { color: colors.grid }, ticks: { color: colors.muted, font: { size: 22, weight: 650 } } }
          }
        }, plugins: [labelPlugin]
      });
    }
    function buildBarCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var colors = axisColors();
      var intel = modelData.slice().sort(function(a,b) { return b.intelligence - a.intelligence; });
      var speed = modelData.slice().sort(function(a,b) { return b.speed - a.speed; });
      var price = modelData.slice().sort(function(a,b) { return a.price - b.price; });
      ChartManager.safeInit('intelligenceChart', { type: 'bar', data: { labels: intel.map(function(d) { return d.model; }), datasets: [{ data: intel.map(function(d) { return d.intelligence; }), backgroundColor: intel.map(function(d) { return d.intelligence >= 55 ? '#38BDF8' : 'rgba(56,189,248,0.46)'; }), borderRadius: 10 }] }, options: baseBarOptions(colors, 60, function(v) { return v + ' AA Index'; }) });
