      ChartManager.safeInit('priceChart', { type: 'bar', data: { labels: price.map(function(d) { return d.model; }), datasets: [{ data: price.map(function(d) { return d.price; }), backgroundColor: price.map(function(d) { return d.price <= 0.4 ? '#22C55E' : (d.price >= 6 ? '#FB7185' : 'rgba(245,158,11,0.58)'); }), borderRadius: 10 }] }, options: baseBarOptions(colors, 10, function(v) { return '$' + Number(v).toFixed(2) + ' / 1M tokens'; }) });
    }
    function buildRankList() {
      var root = document.getElementById('rankList');
      var sorted = modelData.slice().sort(function(a,b) { return b.intelligence - a.intelligence; });
      root.innerHTML = sorted.map(function(d, i) { return '<div class="rank-row"><span class="rank-num">#' + (i + 1) + '</span><span>' + d.full + '</span><span class="rank-score">' + d.intelligence + '</span></div>'; }).join('');
    }
    function buildCharts() { buildTradeoffChart(); buildBarCharts(); buildRankList(); }
    function onThemeChange() { buildCharts(); }
    window.addEventListener('load', buildCharts);
  </script>
</body>
</html>
